package top.pxczxn.community.web.analytics; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import top.pxczxn.community.analytics.application.*; import top.pxczxn.platform.common.result.Result;
@RestController @RequiredArgsConstructor @RequestMapping("/api/v1") public class CreatorAnalyticsController { private final CreatorAnalyticsService service; @GetMapping("/analytics/me") public Result<CreatorAnalyticsView> mine(@RequestParam(required=false)Integer days){return Result.ok(service.mine(days));} @PostMapping("/public/analytics/articles/{articleId}/events") public Result<Void> track(@PathVariable Long articleId,@RequestBody(required=false)TrackRequest request){service.track(articleId,request==null?null:request.sourceType(),request==null?null:request.searchTerm());return Result.ok();} public record TrackRequest(String sourceType,String searchTerm){} }
